    <div v-if="!entry" class="archive-demo-device-choice" role="group" aria-label="Preview device">
      <button v-for="device in ['mobile', 'desktop']" :key="device" type="button" :aria-pressed="mobileDevice === device" @click="mobileDevice = device">{{ device === 'mobile' ? 'Phone' : 'Desktop' }}</button>
    </div>
    <div :id="stageId" ref="stage" class="archive-demo-stage" :style="{ '--phone-width': `${phoneWidth}px` }" :class="[`show-${mobileDevice}`, { 'is-changing': transitioning }]" :role="entry ? 'group' : 'tabpanel'" :aria-label="entry ? 'Personal Archive interaction preview' : null" :aria-labelledby="entry ? null : `${demoId}-${scene}`">
      <figure class="archive-demo-desktop">
        <div class="archive-demo-browser">
          <div class="archive-demo-browser-chrome" aria-hidden="true"><span class="archive-demo-dots"><i/><i/><i/></span><span>henryw.me</span><span class="archive-demo-chrome-spacer"/></div>
          <ArchiveDemoScreen :active="loadPreview" :exhibition="widePreview || mobileDevice === 'desktop'" :visible="visible" :scene="scene" :state="state" :playing="playing" :reduced-motion="reducedMotion" @ready="desktopReady = true" @gallery-ready="galleryDesktopReady = true" />
        </div>
      </figure>
      <figure v-if="!entry" class="archive-demo-mobile">
        <div class="archive-demo-phone">
          <ArchiveDemoScreen :active="loadPreview" :device="mobileDevice" :visible="visible" compact :scene="scene" :state="state" :playing="playing" :reduced-motion="reducedMotion" @ready="phoneReady = true" @gallery-ready="galleryPhoneReady = true" />
        </div>
      </figure>
    </div>
    <div class="archive-demo-playback">
      <div v-if="!entry" class="archive-demo-scenes" role="tablist" aria-label="Interaction demonstrations">
        <button v-for="item in scenes" :key="item.id" type="button" role="tab"
          :id="`${demoId}-${item.id}`" :aria-selected="scene === item.id" :aria-controls="stageId"
          :tabindex="scene === item.id ? 0 : -1" @click="selectScene(item.id)" @keydown="onSceneKey">
          <span class="archive-demo-segment" aria-hidden="true"><i :style="{ transform: `scaleX(${scene === item.id ? elapsed / duration : scenes.findIndex(s => s.id === scene) > scenes.findIndex(s => s.id === item.id) ? 1 : 0})` }"/></span>
          {{ item.label }}
        </button>
      </div>
      <router-link v-else class="archive-demo-entry-link" to="/aipersonalarchive#case-experience">See the interaction <ArrowUpRightIcon /></router-link>
      <button class="archive-demo-transport" type="button" :aria-label="finished ? 'Replay demonstration' : paused ? 'Play demonstration' : 'Pause demonstration'" @click="togglePlayback">
        <svg viewBox="0 0 20 20" aria-hidden="true"><path v-if="finished" d="M4 7a6.5 6.5 0 1 1-.1 6M4 3v4h4"/><path v-else-if="paused" d="m7 4 8 6-8 6Z"/><path v-else d="M7 4v12M13 4v12"/></svg>
      </button>
    </div>
    <div v-if="!entry" class="archive-demo-caption"><p>{{ state.caption }}</p></div>
    <div v-if="!entry" class="archive-demo-try" role="group" aria-label="Explore the archive">
      <span class="archive-demo-try-panel"><ProjectExperienceAction aria-haspopup="dialog" @click="tryDemo">Try it yourself</ProjectExperienceAction><span class="archive-demo-shortcut" aria-hidden="true"><kbd>{{ shortcut }}</kbd><kbd>K</kbd></span></span>
      <ProjectExperienceAction to="/views?presentation=museum&temporaryPresentation=1">Explore <AiViewTerm plural /></ProjectExperienceAction>
    </div>
  </div>
</template>
<script>
import { demoPreloadMargin } from '../../utils/demoPreload';
import ArchiveDemoScreen from './ArchiveDemoScreen.vue';
import AiViewTerm from './AiViewTerm.vue';
import ProjectExperienceAction from './ProjectExperienceAction.vue';
import { archiveDemoState, DEMO_DURATION, HOME_DEMO_TIMING } from '../../utils/archiveDemoTimeline';
export default {
  name: 'ArchiveInteractionDemo', components: { ArchiveDemoScreen, AiViewTerm, ProjectExperienceAction },
  props: { entry: Boolean },
  data: () => ({
    scene: 'home', elapsed: 0, paused: false, visible: false, pageVisible: true,
    transitioning: false, phoneWidth: 230, widePreview: true,
    desktopReady: false, phoneReady: false, loadPreview: false, galleryDesktopReady: false, galleryPhoneReady: false,
    reducedMotion: false, mobileDevice: 'desktop', shortcut: '⌘',
  }),
  computed: {
    demoId() { return `archive-demo-${this.$.uid}`; },
    stageId() { return `${this.demoId}-stage`; },
    scenes() { return [{id:'home',label:'A question becomes a View'},{id:'exhibition',label:'An exhibition'},{id:'gallery',label:'The Gallery'},{id:'palette',label:'Ways to explore'}]; },
    duration() { return DEMO_DURATION[this.scene]; },
    finished() { return this.scene === this.scenes[this.scenes.length - 1].id && this.elapsed >= this.duration; },
    playing() { return this.desktopReady && (this.entry || this.phoneReady) && (this.scene !== 'gallery' || (this.galleryDesktopReady && this.galleryPhoneReady)) && this.visible && this.pageVisible && !this.paused && !this.finished && !this.transitioning; },
    state() { return archiveDemoState(this.scene, this.elapsed); },
  },
  watch: { playing() { this.syncClock(); } },
  created() { this.scene = this.scenes[0].id; },
  mounted() {
    this._wideQuery = matchMedia('(min-width: 641px)');
    this._onWide = () => { this.widePreview = this._wideQuery.matches; };
    this._onWide(); this._wideQuery.addEventListener('change', this._onWide);
    this.shortcut = /Mac|iPhone|iPad/.test(navigator.platform) ? '⌘' : 'Ctrl';
    this._motion = window.matchMedia('(prefers-reduced-motion: reduce)');
    this._motionChange = () => { this.reducedMotion = this._motion.matches; if (this.reducedMotion) { this.paused = true; this.elapsed = this.scene === 'home' ? HOME_DEMO_TIMING.answerCompleteAt : 7000; } };
    this._motionChange(); this._motion.addEventListener('change', this._motionChange);
    this._visibility = () => { this.pageVisible = !document.hidden; };
    this._visibility(); document.addEventListener('visibilitychange', this._visibility);
    this._observer = new IntersectionObserver(entries => { this.visible = entries[0].isIntersecting && entries[0].intersectionRatio >= .35; }, { threshold: [0, .35] });
    this._observer.observe(this.$refs.stage);
    this._preload = new IntersectionObserver(entries => { if (entries[0].isIntersecting) { this.loadPreview = true; this._preload.disconnect(); } }, { rootMargin: demoPreloadMargin() });
    this._preload.observe(this.$refs.exhibit);
    if (!this.entry) {
      const measure = () => {
        const stage = this.$refs.stage, browser = stage.querySelector('.archive-demo-browser');
        const phone = stage.querySelector('.archive-demo-phone');
        const gap = parseFloat(getComputedStyle(stage).columnGap) || 0;
        const browserStyle = getComputedStyle(browser), phoneStyle = getComputedStyle(phone);
        const desktopBorder = parseFloat(browserStyle.borderLeftWidth) + parseFloat(browserStyle.borderRightWidth);
        const phoneInset = parseFloat(phoneStyle.paddingLeft) + parseFloat(phoneStyle.paddingRight) + parseFloat(phoneStyle.borderLeftWidth) + parseFloat(phoneStyle.borderRightWidth);
        const chrome = stage.querySelector('.archive-demo-browser-chrome').getBoundingClientRect().height;
        const ratio = 920 / 1440;
        const nextWidth = (ratio * (stage.clientWidth - gap - desktopBorder) + chrome + desktopBorder + phoneInset) / (2 + ratio);
        if(Math.abs(this.phoneWidth-nextWidth)>.1)this.phoneWidth=nextWidth;
      };
      this._layout = new ResizeObserver(() => { cancelAnimationFrame(this._layoutFrame); this._layoutFrame=requestAnimationFrame(measure); });
      this._layout.observe(this.$refs.stage);
    }
  },
  beforeUnmount() { this._wideQuery?.removeEventListener('change', this._onWide); cancelAnimationFrame(this._frame); cancelAnimationFrame(this._layoutFrame); clearTimeout(this._sceneSwap); clearTimeout(this._sceneReveal); this._observer?.disconnect(); this._preload?.disconnect(); this._layout?.disconnect(); this._motion?.removeEventListener('change', this._motionChange); document.removeEventListener('visibilitychange', this._visibility); },
  methods: {
    syncClock() {
      cancelAnimationFrame(this._frame);
      if (!this.playing) return;
      let last = performance.now();
      const tick = now => {
        if (!this.playing) return;
        this.elapsed = Math.min(this.duration, this.elapsed + Math.min(now - last, 80));
        last = now;
        if (this.elapsed >= this.duration && !this.finished) { this.selectScene(this.entry ? 'palette' : this.scenes[this.scenes.findIndex(s => s.id === this.scene) + 1].id); return; }
        if (!this.finished) this._frame = requestAnimationFrame(tick);
      };
      this._frame = requestAnimationFrame(tick);
    },
    selectScene(scene) {
      clearTimeout(this._sceneSwap); clearTimeout(this._sceneReveal);
      this.transitioning = true;
      this._sceneSwap = setTimeout(() => {
        if (scene === 'gallery' && this.scene !== 'gallery') { this.galleryDesktopReady = false; this.galleryPhoneReady = false; }
        this.scene = scene; this.elapsed = this.reducedMotion ? (scene === 'home' ? HOME_DEMO_TIMING.answerCompleteAt : 7000) : 0; this.paused = this.reducedMotion;
        // Reset the real page while the screen is veiled. Its route transition
        // settles before the next scene appears inside the stationary devices.
        this._sceneReveal = setTimeout(() => { this.transitioning = false; }, this.reducedMotion ? 0 : 430);
      }, this.reducedMotion ? 0 : 180);
    },
    togglePlayback() { if (this.finished) this.selectScene(this.scenes[0].id); else this.paused = !this.paused; },
    onSceneKey(event) {
      if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
      const index = this.scenes.findIndex(item => item.id === this.scene);
      const next = event.key === 'Home' ? 0 : event.key === 'End' ? this.scenes.length - 1 : (index + (event.key === 'ArrowRight' ? 1 : -1) + this.scenes.length) % this.scenes.length;
      const target = this.scenes[next].id;
      event.preventDefault(); this.selectScene(target);
      this.$el.querySelector(`#${this.demoId}-${target}`)?.focus({ preventScroll: true });
    },
    tryDemo() {
      window.dispatchEvent(new CustomEvent('open-site-search'));
    },
  },
};
</script>
